import React from "react";
import { useLocation } from "react-router-dom";
import Telephone from "../../../../assets/icons/telephone.png";
import Mail from "../../../../assets/icons/mail.png";
import Time from "../../../../assets/icons/time.png";
import "../DoctorProfile.css";

const TimeTable = () => {
  const location = useLocation();
  const { doctor } = location.state; // Access the doctor data passed via navigate

  return (
    <div className="p-2 bg-white">
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 items-center">
        <div className="p-6 rounded-md shadow-lg">
          <ul>
            {doctor.checkupData.map((schedule, index) => (
              <li
                key={index}
                className="flex justify-between items-center mb-4 text-gray-700"
              >
                <span className="flex items-center text-gray-700">
                  <img src={Time} alt="Time" className="h-4 w-4 mr-2" />
                  {new Date(schedule.date).toLocaleDateString()}
                </span>
                <span className="text-blue-500">
                  {schedule.times.length > 0
                    ? `${schedule.times[0].startTime} - ${schedule.times[0].endTime}`
                    : "No time available"}
                </span>
              </li>
            ))}
          </ul>
        </div>

        <div className="sm:col-span-2 flex flex-col sm:flex-row justify-center items-center">
          <div className="flex flex-col items-center text-center mb-4 sm:mb-0 sm:mr-6">
            <span className="inline-block p-3 bg-blue-100 rounded-md mb-4">
              <img src={Telephone} alt="Telephone" className="h-6 w-6" />
            </span>
            <div>
              <h3 className="text-lg font-semibold">Phone</h3>
              <p className="text-gray-600">
                {doctor.firstName} is available for consultation.
              </p>
              <a href={`tel:${doctor.contact}`} className="text-blue-600">
                {doctor.contact}
              </a>
            </div>
          </div>
          <div className="flex flex-col items-center text-center">
            <span className="inline-block p-3 bg-blue-100 rounded-md mb-4">
              <img src={Mail} alt="Mail" className="h-6 w-6" />
            </span>
            <div>
              <h3 className="text-lg font-semibold">Email</h3>
              <p className="text-gray-600">
                You can contact {doctor.firstName} for assistance.
              </p>
              <a href={`mailto:${doctor.email}`} className="text-blue-600">
                {doctor.email}
              </a>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TimeTable;
